import numpy as np, random, ot
from scipy.optimize import linear_sum_assignment

def test_once(seed,n):
    random.seed(seed); np.random.seed(seed)
    a=ot.utils.unif(n); b=ot.utils.unif(n)
    source=np.random.rand(n,2)
    target=np.random.rand(n,2)
    M=ot.dist(source,target)
    G1=ot.lp.emd(a,b,M,check_marginals=False)
    r,c=linear_sum_assignment(M)
    G2=np.zeros_like(M)
    for i,j in zip(r,c):
        G2[i,j]=a[i]
    return np.max(np.abs(G1-G2))
for n in [2,3,4,5,10,30,50,100]:
    for seed in range(0,10):
        diff=test_once(seed,n)
        if diff>1e-9:
            print('Mismatch', n, seed, diff)
            raise SystemExit
print('all ok')
