import ot, numpy as np, random
from scipy.optimize import linear_sum_assignment

def simple_match(a,b,M):
    n=len(a)
    tgt_available=set(range(n))
    plan=np.zeros_like(M)
    # row-by-row greedy pick nearest available target
    for i in range(n):
        j_candidates=np.argsort(M[i])
        for j in j_candidates:
            if j in tgt_available:
                tgt_available.remove(j)
                plan[i,j]=a[i]
                break
    return plan

def test(n, trials=100):
    for seed in range(trials):
        random.seed(seed); np.random.seed(seed)
        a=ot.utils.unif(n); b=a
        M=ot.dist(np.random.rand(n,2), np.random.rand(n,2))
        P1=simple_match(a,b,M)
        P2=ot.lp.emd(a,b,np.ascontiguousarray(M),check_marginals=False)
        if not np.allclose(P1,P2):
            return False, seed
    return True, None
for n in [50,100,200,300,600]:
    ok,seed=test(n,100)
    print(n, ok)
